package org.cttelsamicsterrassa.data.core.application.player.find;
import org.albertsanso.commons.query.*; import org.cttelsamicsterrassa.data.core.domain.player.model.FederatedPlayer; import org.cttelsamicsterrassa.data.core.domain.player.repository.FederatedPlayerRepository; import javax.inject.*;
@Named public class FindFederatedPlayerBySourceAndNameQueryHandler extends DomainQueryHandler<FindFederatedPlayerBySourceAndNameQuery,FederatedPlayer>{private final FederatedPlayerRepository r;@Inject public FindFederatedPlayerBySourceAndNameQueryHandler(FederatedPlayerRepository r){this.r=r;}public DomainQueryResponse<FederatedPlayer> handle(FindFederatedPlayerBySourceAndNameQuery q){return r.findFederatedPlayerBySourceAndName(q.getSource(),q.getName()).map(DomainQueryResponse::sucessResponse).orElseGet(()->DomainQueryResponse.failResponse(null));}}
